package com.hobbycoders.aishuffle.account

import android.content.Context
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import org.json.JSONObject
import java.security.SecureRandom
import java.time.Instant
import java.util.UUID
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// Deliberately not a data class: tokens must never enter autogenerated toString().
class AccountSession(val hub: String, val token: String, val expiresAt: String, val deviceId: String, val accountId: String, val username: String, val profileComplete: Boolean? = null) {
    fun json() = JSONObject().put("hub", hub).put("access_token", token).put("expires_at", expiresAt)
        .put("device_id", deviceId).put("account", JSONObject().put("id", accountId).put("username", username)
            .apply { profileComplete?.let { put("profile_complete", it) } })
    companion object {
        fun parse(hub: String, j: JSONObject): AccountSession {
            require(j.optString("access_token").isNotBlank() && !j.optString("access_token").contains(Regex("[\\r\\n]"))) { "The hub returned an invalid authorization." }
            require(Instant.parse(j.getString("expires_at")).isAfter(Instant.now())) { "This sign-in expired. Sign in again." }
            val account = j.getJSONObject("account")
            val complete = if (account.has("profile_complete")) account.get("profile_complete") as? Boolean
                ?: error("The service returned an invalid account profile.") else null
            return AccountSession(PairingInput.origin(hub), j.getString("access_token"), j.getString("expires_at"), j.getString("device_id"), account.getString("id"), account.getString("username"), complete)
        }
    }
}

class AccountStore internal constructor(private val prefs: android.content.SharedPreferences) {
    companion object { const val DEFAULT_HUB = "https://hobbycoders.com" }
    constructor(context: Context) : this(EncryptedSharedPreferences.create(context.applicationContext, "account_secure", MasterKey.Builder(context.applicationContext).setKeyScheme(MasterKey.KeyScheme.AES256_GCM).build(), EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV, EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM))
    /**
     * The account device id for the next sign-in. This installation keeps one
     * id across sign-ins (an expired week-long session included), so workers
     * renew its entry instead of listing the phone again. A new id only after
     * an explicit sign-out, a revocation, or when [fresh] is asked for (an
     * account service or flow that cannot reuse a known id).
     */
    fun beginSignIn(fresh: Boolean = false): String {
        prefs.getString("install_id", null)?.takeIf { !fresh }?.let { return it }
        return UUID.randomUUID().toString().also {
            prefs.edit().putString("install_id", it).putString("install_secret", newSecret()).commit()
        }
    }
    /** Whether [beginSignIn] would reuse an id that an earlier sign-in already used. */
    fun hasInstallIdentity() = prefs.contains("install_id")
    /** The account service's last /v1/oauth/start said it accepts a known device id. */
    var hubReusesDevices: Boolean
        get() = prefs.getBoolean("hub_device_reuse", false)
        set(value) { prefs.edit().putBoolean("hub_device_reuse", value).commit() }
    /**
     * Proof that a worker enrollment comes from THIS installation, distinct per
     * worker so one worker cannot replay it to another. Only the hash is kept
     * by the worker; with it the worker renews this phone's entry and keeps its
     * approval, which a hub ticket alone (account password) cannot do.
     */
    fun installProof(serverId: String): String {
        val secret = prefs.getString("install_secret", null)
            ?: newSecret().also { prefs.edit().putString("install_secret", it).commit() }
        val mac = Mac.getInstance("HmacSHA256").apply { init(SecretKeySpec(secret.toByteArray(), "HmacSHA256")) }
        return mac.doFinal("shuffle-install-proof:$serverId".toByteArray()).joinToString("") { "%02x".format(it) }
    }
    private fun newSecret() = ByteArray(32).also { SecureRandom().nextBytes(it) }.joinToString("") { "%02x".format(it) }
    var pendingOAuth: String?
        get() = prefs.getString("oauth_pending", null)
        set(value) { prefs.edit().putString("oauth_pending", value).commit() }
    val installId: String get() = prefs.getString("install_id", null) ?: UUID.randomUUID().toString().also { prefs.edit().putString("install_id", it).commit() }
    var hub: String
        get() = prefs.getString("hub", null)?.takeIf { it.isNotBlank() } ?: DEFAULT_HUB
        set(value) { prefs.edit().putString("hub", PairingInput.origin(value)).commit() }
    fun session(): AccountSession? = prefs.getString("session", null)?.let { runCatching { AccountSession.parse(hub, JSONObject(it)) }.getOrNull() }
    fun save(session: AccountSession) { prefs.edit().putString("hub", session.hub).putString("install_id", session.deviceId).putString("session", session.json().toString()).commit() }
    fun updateProfile(expected: AccountSession, username: String, complete: Boolean): AccountSession {
        val current = session()
        check(current != null && current.token == expected.token && current.hub == expected.hub &&
            current.accountId == expected.accountId && current.deviceId == expected.deviceId) { "Your account changed. Open account settings again." }
        return AccountSession(current.hub, current.token, current.expiresAt, current.deviceId, current.accountId, username, complete)
            .also(::save)
    }
    fun hasStoredSession() = prefs.contains("session")
    /** [forgetInstall]: an explicit sign-out or revocation; the next sign-in is a new device. */
    fun clear(forgetInstall: Boolean = false) {
        prefs.edit().remove("session").remove("oauth_pending").apply {
            if (forgetInstall) remove("install_id").remove("install_secret")
        }.commit()
    }
    fun pendingLink(serverId: String, session: AccountSession): JSONObject? = prefs.getString("link:$serverId", null)?.let {
        JSONObject(it).takeIf { value -> value.optString("account_id") == session.accountId && value.optString("hub") == session.hub }
    }
    fun savePendingLink(serverId: String, session: AccountSession, registration: JSONObject) {
        prefs.edit().putString("link:$serverId", JSONObject().put("hub", session.hub).put("account_id", session.accountId).put("registration", registration).toString()).commit()
    }
    fun clearPendingLink(serverId: String) { prefs.edit().remove("link:$serverId").commit() }
    fun matches(session: AccountSession) = session()?.let { current -> current.token == session.token &&
        current.hub == session.hub && current.accountId == session.accountId && current.deviceId == session.deviceId } == true
}
